<?php
declare(strict_types=1);
require dirname(__DIR__) . '/common.php';$actorId=dxf_admin_guard($pdo,DXF_PERMISSION_REVIEW);$id=dxf_positive_id($_GET['id']??0);$q=$pdo->prepare('SELECT s.*,v.display_title AS title,v.workflow_mode,v.descriptor_json,v.descriptor_sha256 FROM dxf_submissions s JOIN dxf_template_versions v ON v.id=s.template_version_id AND v.template_id=s.template_id WHERE s.id=? LIMIT 1');$q->execute([$id]);$submission=$q->fetch(PDO::FETCH_ASSOC);if(!is_array($submission)){adiwira_render_404();return;}$descriptor=dxf_descriptor_validate((array)json_decode((string)$submission['descriptor_json'],true,32,JSON_THROW_ON_ERROR));$values=(array)json_decode((string)$submission['values_json'],true,32,JSON_THROW_ON_ERROR);$identity=(array)json_decode((string)$submission['identity_json'],true,16,JSON_THROW_ON_ERROR);if(!hash_equals((string)$submission['descriptor_sha256'],hash('sha256',dxf_descriptor_json($descriptor)))||!hash_equals((string)$submission['values_sha256'],hash('sha256',dxf_values_json($descriptor,$values)))||!hash_equals((string)$submission['identity_sha256'],hash('sha256',dxf_identity_json($identity))))throw new RuntimeException('Submission integrity check failed.');$events=$pdo->prepare('SELECT event_key,actor_user_id,metadata_json,created_at_utc FROM dxf_submission_events WHERE submission_id=? ORDER BY id');$events->execute([$id]);$events=$events->fetchAll(PDO::FETCH_ASSOC)?:[];
?>
<div class="dxf-admin"><?php dxf_admin_nav($pdo,$actorId,'workspace');?><header class="dxf-admin-head"><div><span><?=dxf_h(dxf_t('Submission details'))?></span><h1><?=dxf_h($submission['title'])?></h1><p><code><?=dxf_h($submission['public_id'])?></code> · <?=dxf_h(dxf_t(ucfirst((string)$submission['status'])))?></p></div></header>
<div class="dxf-review-grid"><section class="dxf-admin-card"><h2><?=dxf_h(dxf_t('Identity'))?></h2><dl><?php foreach($identity as $key=>$value):?><div><dt><?=dxf_h(dxf_t(ucwords(str_replace('_',' ',$key))))?></dt><dd><?=dxf_h(is_bool($value)?($value?dxf_t('Yes'):dxf_t('No')):$value)?></dd></div><?php endforeach;?></dl><h2><?=dxf_h(dxf_t('Submitted values'))?></h2><dl><?php foreach($descriptor['fields'] as $field):?><div><dt><?=dxf_h($field['label'])?></dt><dd><?=dxf_h($values[$field['key']]??'')?></dd></div><?php endforeach;?></dl></section>
<aside class="dxf-admin-card"><h2><?=dxf_h(dxf_t('Decision'))?></h2><?php if($submission['status']==='pending'):?><form method="post" action="<?=dxf_h(dxf_admin_url('submissions/review'))?>"><input type="hidden" name="csrf_token" value="<?=dxf_h(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="version" value="<?=(int)$submission['version']?>"><label><?=dxf_h(dxf_t('Review reason'))?><textarea class="inp" name="reason" maxlength="1000"></textarea></label><div class="dxf-actions"><button class="adam-btn" name="decision" value="approve" type="submit"><?=dxf_h(dxf_t('Approve'))?></button><button class="adam-btn dxf-danger" name="decision" value="reject" type="submit"><?=dxf_h(dxf_t('Reject'))?></button></div></form><?php elseif($submission['status']==='ready'):?><p><?=dxf_h(dxf_t('Output was generated automatically when the form was submitted.'))?></p><?php else:?><p><?=dxf_h($submission['review_reason']??dxf_t('No review reason recorded.'))?></p><?php endif;?><?php if($submission['receipt_revoked_at_utc']===null):?><form method="post" action="<?=dxf_h(dxf_admin_url('submissions/review'))?>"><input type="hidden" name="csrf_token" value="<?=dxf_h(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="version" value="<?=(int)$submission['version']?>"><label><?=dxf_h(dxf_t('Receipt revocation reason'))?><textarea class="inp" name="reason" maxlength="1000" required></textarea></label><button class="adam-btn dxf-danger" name="decision" value="revoke_receipt" type="submit"><?=dxf_h(dxf_t('Revoke receipt access'))?></button></form><?php else:?><p><?=dxf_h(dxf_t('Receipt access has been revoked.'))?></p><?php endif;?><h2><?=dxf_h(dxf_t('Immutable events'))?></h2><ol class="dxf-events"><?php foreach($events as $event):?><li><strong><?=dxf_h(dxf_t(ucwords(str_replace('_',' ',$event['event_key']))))?></strong><span><?=dxf_h(dxf_admin_datetime($event['created_at_utc']))?><?php if($event['actor_user_id']):?> · #<?=(int)$event['actor_user_id']?><?php endif;?></span></li><?php endforeach;?></ol></aside></div></div>
